import { makeSculpture } from './parts/sculpture.js';
import vertexShader from './shaders/glow.vert';
import fragmentShader from './shaders/glow.frag';

export async function createProject({ THREE, container, state }) {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#101827');
  const camera = new THREE.PerspectiveCamera(55, 1, 0.1, 100);
  camera.position.set(3, 2.5, 5);
  camera.lookAt(0, 0, 0);
  const renderer = new THREE.WebGLRenderer({antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  container.appendChild(renderer.domElement);
  const {mesh, geometry, material} = makeSculpture({vertexShader, fragmentShader});
  scene.add(mesh);
  let speed = state?.speed ?? 0.6;
  const resize = () => {
    const width = container.clientWidth || 1, height = container.clientHeight || 1;
    renderer.setSize(width,height);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  };
  const observer = new ResizeObserver(resize);
  observer.observe(container);
  resize();
  return {
    scene,camera,renderer,
    setup({scene:api}) {
      api.registerEntity({id:'sculpture',label:'发光雕塑',object:mesh,read:()=>({speed})});
      api.registerAction({target:'sculpture',name:'setSpeed',description:'调节旋转速度',
        parameters:{type:'object',properties:{speed:{type:'number',minimum:0,maximum:5}},
          required:['speed'],additionalProperties:false},
        execute({speed:next}){speed=next;},
        verify({args,after}){return after.speed===args.speed;}
      });
    },
    update({dt}) {
      mesh.rotation.y+=dt*speed;
      material.uniforms.time.value+=dt;
    },
    serialize(){return {speed};},
    restore(saved){speed=saved?.speed ?? speed;},
    dispose(){observer.disconnect();geometry.dispose();material.dispose();renderer.dispose();}
  };
}

