import { TorusKnotGeometry, Mesh, ShaderMaterial } from 'three';
export function makeSculpture({vertexShader,fragmentShader}) {
  const geometry=new TorusKnotGeometry(1,0.24,120,16);
  const material=new ShaderMaterial({
    uniforms:{time:{value:0}},vertexShader,fragmentShader
  });
  return {mesh:new Mesh(geometry,material),geometry,material};
}

